package local.skyfamily;
import android.content.Context;import android.graphics.*;import android.view.*;import org.json.*;import java.util.*;
final class StudyInk extends View {
 static class Stroke{int color;float width;ArrayList<PointF> points=new ArrayList<>();Stroke(int c,float w){color=c;width=w;}}
 static class Model{ArrayList<Stroke> strokes=new ArrayList<>();Stroke active;int points=0;boolean begin(float x,float y,int c,float w){if(points>=12000||strokes.size()>=400)return false;active=new Stroke(c,w);strokes.add(active);add(x,y);return true;}void add(float x,float y){if(active==null||points>=12000)return;active.points.add(new PointF(Math.max(0,Math.min(1,x)),Math.max(0,Math.min(1,y))));points++;}void end(){active=null;}void cancel(){if(active!=null){points-=active.points.size();strokes.remove(active);active=null;}}void undo(){end();if(!strokes.isEmpty())points-=strokes.remove(strokes.size()-1).points.size();}void clear(){strokes.clear();active=null;points=0;}
 String json(){JSONArray a=new JSONArray();try{for(Stroke s:strokes){JSONArray p=new JSONArray();for(PointF v:s.points){p.put(Math.round(v.x*1000));p.put(Math.round(v.y*1000));}a.put(new JSONObject().put("c",s.color).put("w",s.width).put("p",p));}}catch(Exception e){throw new IllegalStateException(e);}return a.toString();}
 static Model parse(String value)throws Exception{if(value.length()>300000)throw new Exception("Ink data too large");Model m=new Model();JSONArray a=new JSONArray(value);if(a.length()>400)throw new Exception("Too many strokes");for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);float width=(float)o.getDouble("w");if(width<1||width>60||Float.isNaN(width))throw new Exception("Invalid pen width");Stroke s=new Stroke(o.getInt("c"),width);JSONArray p=o.getJSONArray("p");if(p.length()%2!=0||p.length()<2)throw new Exception("Invalid stroke");for(int n=0;n<p.length();n+=2){int x=p.getInt(n),y=p.getInt(n+1);if(x<0||y<0||x>1000||y>1000||++m.points>12000)throw new Exception("Invalid ink points");s.points.add(new PointF(x/1000f,y/1000f));}m.strokes.add(s);}return m;}
 void draw(Canvas c,RectF box){c.save();c.clipRect(box);Paint pen=new Paint(3);pen.setStrokeCap(Paint.Cap.ROUND);pen.setStrokeJoin(Paint.Join.ROUND);for(Stroke s:strokes){pen.setColor(s.color);pen.setStrokeWidth(s.width*box.width()/1000f);if(s.points.size()==1){PointF v=s.points.get(0);pen.setStyle(Paint.Style.FILL);c.drawCircle(box.left+v.x*box.width(),box.top+v.y*box.height(),pen.getStrokeWidth()/2,pen);}else{Path path=new Path();boolean first=true;for(PointF v:s.points){float x=box.left+v.x*box.width(),y=box.top+v.y*box.height();if(first){path.moveTo(x,y);first=false;}else path.lineTo(x,y);}pen.setStyle(Paint.Style.STROKE);c.drawPath(path,pen);}}c.restore();}}
 final Model model;final Runnable changed;boolean writing=false;int color=0xff245cb3;float width=4;StudyInk(Context c,Model m,Runnable callback){super(c);model=m;changed=callback;setContentDescription("Saved school handwriting canvas. Choose Draw or Highlight before writing; Scroll lets the page move.");}
 protected void onDraw(Canvas c){c.drawColor(Color.WHITE);Paint p=new Paint();p.setColor(0xffdce7f1);for(int y=24;y<getHeight();y+=28)c.drawLine(0,y,getWidth(),y,p);model.draw(c,new RectF(0,0,getWidth(),getHeight()));}
 public boolean onTouchEvent(MotionEvent e){if(!writing)return false;int action=e.getActionMasked();if(e.getPointerCount()>1){model.cancel();invalidate();return true;}if(action==MotionEvent.ACTION_DOWN){getParent().requestDisallowInterceptTouchEvent(true);if(!model.begin(e.getX()/getWidth(),e.getY()/getHeight(),color,width))android.widget.Toast.makeText(getContext(),"Ink limit reached; undo or use another page",1).show();}else if(action==MotionEvent.ACTION_MOVE)model.add(e.getX()/getWidth(),e.getY()/getHeight());else if(action==MotionEvent.ACTION_UP){model.end();changed.run();getParent().requestDisallowInterceptTouchEvent(false);performClick();}else if(action==MotionEvent.ACTION_CANCEL){model.cancel();getParent().requestDisallowInterceptTouchEvent(false);}invalidate();return true;}public boolean performClick(){super.performClick();return true;}
}
